def enrichir(base, constructeur):
    """Ajoute les ateliers officiels APRÈS les leçons V4 pour préserver les clés de sauvegarde."""
    produced={k:list(v) for k,v in base.items()}
    count=0
    for lineno, raw in enumerate(DATA.strip().splitlines(),1):
        parts=[p.strip() for p in raw.split('|')]
        if len(parts)!=11:
            raise ValueError(f'Atelier invalide ligne {lineno}: {len(parts)} colonnes')
        grade, axis, title, rule, examples, passage, question, options, answer, mission, skill=parts
        choices=options.split(';')
        lesson=constructeur(title,rule,examples,passage,question,choices,answer,mission)
        lesson.update(axe=axis,competence=skill,origine='Atelier original inspiré des programmes français LVE')
        produced[grade].append(lesson)
        count+=1
    if count!=56:
        raise AssertionError(f'56 ateliers prévus, {count} produits')
    if set(produced)!=set(PROGRAMMES):
        raise AssertionError('Classes non conformes')
    return produced
